package pe.eltumi.erp;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import java.util.*;
import java.math.*;
import java.time.*;
import java.time.temporal.ChronoUnit;
import static pe.eltumi.erp.Store.*;
@Service
public class ErpService {
 final Store db;final Catalog cat;final Access access;final Ledger ledger;final Inventory inventory;final HumanResources hr;final Sales sales;final BCryptPasswordEncoder passwords;
 public ErpService(Store d,Catalog c,Access a,Ledger l,Inventory i,HumanResources h,Sales s,BCryptPasswordEncoder p){db=d;cat=c;access=a;ledger=l;inventory=i;hr=h;sales=s;passwords=p;}
 void serialize(){db.lock("company",1);}
 public Map<String,Object> safe(String entity,Map<String,Object>b){var r=new LinkedHashMap<>(b);r.remove("password_hash");r.remove("totp_secret");r.remove("locked_until");r.remove("failed_attempts");if(entity.equals("invoices")){r.remove("company_snapshot");r.remove("lines_snapshot");}return r;}
 public Map<String,Object> list(String entity,String query,String status,String from,String to,int page,int size){access.entity(entity,"read");size=Math.min(Math.max(size,1),500);page=Math.max(page,0);var args=new ArrayList<Object>();var clauses=new ArrayList<String>();String textField=cat.fields(entity).stream().filter(f->List.of("name","code","party","description","customer","username").contains(str(f,"key"))).map(f->str(f,"key")).findFirst().orElse("id");if(!query.isBlank()){if(textField.equals("id")){try{clauses.add("id=?");args.add(Long.parseLong(query));}catch(Exception e){clauses.add("1=0");}}else{clauses.add("LOWER("+textField+") LIKE ?");args.add("%"+query.toLowerCase()+"%");}}
 if(!status.isBlank()&&cat.fields(entity).stream().anyMatch(f->str(f,"key").equals("status"))){clauses.add("status=?");args.add(status);}String dateField=cat.fields(entity).stream().filter(f->str(f,"type").equals("date")).map(f->str(f,"key")).findFirst().orElse("created_at");if(!from.isBlank()){clauses.add(dateField+">=?");args.add(LocalDate.parse(from));}if(!to.isBlank()){clauses.add(dateField+"<?");args.add(LocalDate.parse(to).plusDays(1));}String where=clauses.isEmpty()?"":" WHERE "+String.join(" AND ",clauses);long count=db.count("SELECT COUNT(*) FROM "+entity+where,args.toArray());args.add(size);args.add(page*size);return map("items",db.rows("SELECT * FROM "+entity+where+" ORDER BY id DESC LIMIT ? OFFSET ?",args.toArray()).stream().map(x->safe(entity,x)).toList(),"total",count,"page",page,"size",size);}
 public Map<String,Object> detail(String entity,long id){access.entity(entity,"read");var row=safe(entity,db.get(entity,id));String table=switch(entity){case "purchases"->"purchase_lines";case "receipts"->"receipt_lines";case "orders"->"order_lines";case "quotes"->"quote_lines";case "journals"->"journal_lines";case "dishes"->"recipes";case "loans"->"installments";default->"";};if(!table.isBlank()){String column=switch(entity){case "purchases"->"purchase_id";case "receipts"->"receipt_id";case "orders"->"order_id";case "quotes"->"quote_id";case "journals"->"journal_id";case "dishes"->"dish_id";default->"loan_id";};row.put("lines",db.rows("SELECT * FROM "+table+" WHERE "+column+"=?",id));}if(List.of("payables","receivables").contains(entity))row.put("payments",db.rows("SELECT * FROM payments WHERE side=? AND debt_id=?",entity,id));return row;}
 void validate(String entity,Map<String,Object>b,long editing){for(var f:cat.fields(entity)){String key=str(f,"key");if(f.containsKey("ref")&&id(b,key)>0)db.get(str(f,"ref"),id(b,key));if(str(f,"type").equals("file")&&!str(b,key).isBlank()){var file=db.one("SELECT * FROM files WHERE id=?",str(b,key));access.module(str(file,"module"),"read");}}
 if(b.containsKey("start_date")&&b.get("start_date")!=null&&b.get("end_date")!=null)require(!LocalDate.parse(str(b,"end_date")).isBefore(LocalDate.parse(str(b,"start_date"))),"La fecha final no puede ser anterior al inicio");
 if(entity.equals("products")||entity.equals("dishes"))require(dec(b,"tax_rate").compareTo(new BigDecimal("100"))<=0,"Tasa de impuesto inválida");
 if(entity.equals("discounts"))require(dec(b,"percent").compareTo(new BigDecimal("100"))<0,"El descuento debe ser menor a 100%");
 if(entity.equals("stock_rules"))require(dec(b,"maximum").compareTo(dec(b,"minimum"))>0,"El máximo debe superar al mínimo");
 if(entity.equals("budgets"))require(dec(b,"amount").compareTo(dec(b,"executed"))>=0,"El presupuesto no puede ser menor a lo ejecutado");
 if(entity.equals("accounts")&&id(b,"parent_id")>0){long parent=id(b,"parent_id");Set<Long>seen=new HashSet<>();while(parent>0){require(parent!=editing&&seen.add(parent),"La jerarquía de cuentas no puede contener ciclos");parent=id(db.get("accounts",parent),"parent_id");}}
 if(entity.equals("dining_tables")){long area=id(b,"area_id");require(db.count("SELECT COUNT(*) FROM dining_tables WHERE area_id=? AND id<>?",area,editing)<dec(db.get("areas",area),"max_tables").longValue(),"El área llegó al máximo de mesas");}
 if(entity.equals("contracts")){positive(dec(b,"salary"));for(String k:List.of("pension_rate","health_rate"))require(dec(b,k).compareTo(new BigDecimal("100"))<=0,"Tasa inválida");if(str(b,"status").equals("ACTIVO"))require(db.count("SELECT COUNT(*) FROM contracts WHERE employee_id=? AND status='ACTIVO' AND id<>? AND start_date<=? AND end_date>=?",id(b,"employee_id"),editing,str(b,"end_date"),str(b,"start_date"))==0,"Existe un contrato activo con fechas superpuestas");}
 if(entity.equals("attendance")){if(!str(b,"check_in").isBlank()&&!str(b,"check_out").isBlank())require(LocalDateTime.parse(str(b,"check_out")).isAfter(LocalDateTime.parse(str(b,"check_in"))),"La salida debe ser posterior al ingreso");}
 if(entity.equals("company"))require(str(b,"ruc").matches("\\d{11}"),"El RUC debe tener 11 dígitos");
 }
 @Transactional public Map<String,Object> create(String entity,Map<String,Object>body){access.entity(entity,"write");serialize();require(!List.of("company","audit","stocks","stock_moves","receipts","journals","invoices").contains(entity),"Usa el proceso correspondiente para crear este registro");var b=cat.clean(entity,body,false);for(var f:cat.fields(entity))if(Boolean.TRUE.equals(f.get("readonly"))&&f.containsKey("default"))b.put(str(f,"key"),f.get("default"));validate(entity,b,0);long id;
 if(entity.equals("users")){String p=str(b,"password");require(p.length()>=10&&p.length()<=72,"La contraseña debe tener de 10 a 72 caracteres");b.remove("password");b.put("password_hash",passwords.encode(p));b.put("email",str(b,"email").toLowerCase());id=db.insert(entity,b);}
 else if(entity.equals("purchases"))id=inventory.purchase(body,b);
 else if(entity.equals("orders"))id=sales.createOrder(body,b);
 else if(entity.equals("quotes"))id=sales.quote(body,b);
 else if(List.of("leaves","payrolls","fees","benefits","loans","advances","settlements").contains(entity))id=hr.create(entity,b);
 else if(entity.equals("cash_sessions")){long account=id(b,"cash_account_id");var a=db.get("cash_accounts",account);require(str(a,"kind").equals("EFECTIVO"),"La apertura corresponde a una cuenta en efectivo");require(db.count("SELECT COUNT(*) FROM cash_sessions WHERE cash_account_id=? AND status='ABIERTA'",account)==0,"La caja ya está abierta");require(dec(b,"opening").compareTo(dec(a,"balance"))==0,"El fondo inicial debe coincidir con el saldo de tesorería: "+str(a,"balance"));b.put("opened_at",LocalDateTime.now().toString());b.put("opened_by",Security.user().id());b.put("expected",b.get("opening"));id=db.insert(entity,b);}
 else if(entity.equals("treasury")){var amount=dec(b,"amount");id=ledger.cash(id(b,"cash_account_id"),amount,str(b,"kind"),str(b,"description"),"MANUAL",str(b,"file_id"),LocalDate.parse(str(b,"date")));ledger.simple(str(b,"kind").equals("INGRESO")?ledger.cashCode(id(b,"cash_account_id")):"659",str(b,"kind").equals("INGRESO")?"501":ledger.cashCode(id(b,"cash_account_id")),amount,str(b,"description"),"treasury:"+id,LocalDate.parse(str(b,"date")));}
 else if(List.of("payables","receivables").contains(entity)){positive(dec(b,"total"));b.put("source","MANUAL");id=db.insert(entity,b);ledger.simple(entity.equals("receivables")?"121":"659",entity.equals("receivables")?"501":"421",dec(b,"total"),"Registro manual de cuenta",entity+":"+id,LocalDate.parse(str(b,"date")));}
 else if(List.of("assets","services","obligations").contains(entity)){positive(dec(b,"amount"));if(entity.equals("assets")){positive(dec(b,"useful_months"));require(dec(b,"residual").compareTo(dec(b,"amount"))<0,"El residual debe ser menor al costo");}ledger.budget(id(b,"budget_id"),dec(b,"amount"),LocalDate.parse(str(b,"date")));id=db.insert(entity,b);String party=entity.equals("obligations")?str(b,"party"):str(db.get("partners",id(b,"partner_id")),"name");ledger.debt("payables",party,"",dec(b,"amount"),LocalDate.parse(str(b,entity.equals("assets")?"date":"due_date")),entity,id,str(b,"name"));ledger.simple(entity.equals("assets")?"331":"631","421",dec(b,"amount"),str(b,"name"),entity+":"+id,LocalDate.parse(str(b,"date")));}
 else {if(entity.equals("periods")){access.entity(entity,"approve");require(YearMonth.parse(str(b,"period")).isBefore(YearMonth.from(today())),"Solo se cierran meses anteriores al actual");}id=db.insert(entity,b);}
 access.audit("CREAR",entity,id,"Registro creado");return safe(entity,db.get(entity,id));}
 @Transactional public Map<String,Object> edit(String entity,long id,Map<String,Object>body){access.entity(entity,"write");serialize();var old=db.lock(entity,id);require(!entity.equals("assets"),"Los importes del activo ya están contabilizados; usa adjuntos, depreciación o baja");require(!body.containsKey("lines"),"Las líneas no se modifican desde la edición de cabecera");require(body.containsKey("version")&&id(body,"version")==id(old,"version"),"El registro cambió. Recarga antes de editar");boolean draft=List.of("fees","payrolls").contains(entity)&&str(old,"status").equals("BORRADOR");require(!Boolean.TRUE.equals(cat.entity(entity).get("readonly"))||draft,"Este registro se modifica mediante sus acciones");require(!entity.equals("purchases")||str(old,"status").equals("BORRADOR"),"La compra ya fue enviada");var b=cat.clean(entity,body,true);var merged=new LinkedHashMap<>(old);merged.putAll(b);validate(entity,merged,id);if(entity.equals("dining_tables"))require(str(old,"status").equals("LIBRE"),"Solo se editan mesas libres");if(entity.equals("users")){String p=str(b,"password");b.remove("password");if(!p.isBlank()){require(p.length()>=10&&p.length()<=72,"Usa de 10 a 72 caracteres");b.put("password_hash",passwords.encode(p));db.exec("DELETE FROM sessions WHERE user_id=?",id);}if(b.containsKey("email"))b.put("email",str(b,"email").toLowerCase());if(id==Security.user().id())require(str(merged,"status").equals("ACTIVO")&&str(merged,"role").equals("ADMIN"),"No puedes bloquear ni quitar tu propio rol administrador");if(str(old,"role").equals("ADMIN")&&(!str(merged,"role").equals("ADMIN")||!str(merged,"status").equals("ACTIVO")))require(db.count("SELECT COUNT(*) FROM users WHERE role='ADMIN' AND status='ACTIVO' AND id<>?",id)>0,"Debe existir un administrador activo");}
 if(entity.equals("cash_accounts")&&db.count("SELECT COUNT(*) FROM treasury WHERE cash_account_id=?",id)>0)require(str(merged,"kind").equals(str(old,"kind")),"No se cambia el tipo de una cuenta con movimientos");if(entity.equals("products")&&(db.count("SELECT COUNT(*) FROM stock_moves WHERE product_id=?",id)>0||db.count("SELECT COUNT(*) FROM recipes WHERE product_id=?",id)>0))require(str(merged,"unit").equals(str(old,"unit")),"La unidad base está vinculada a recetas o movimientos");if(entity.equals("accounts")&&db.count("SELECT COUNT(*) FROM journal_lines WHERE account_id=?",id)>0)require(str(merged,"code").equals(str(old,"code"))&&str(merged,"type").equals(str(old,"type")),"No se cambia el código ni tipo de una cuenta con movimientos");
 if(draft&&entity.equals("payrolls"))require(b.keySet().stream().allMatch(k->List.of("file_id","notes").contains(k)),"Elimina el borrador para recalcular sus importes");if(draft&&entity.equals("fees")){hr.recalculateFee(merged);b.put("withheld",merged.get("withheld"));b.put("net",merged.get("net"));}db.update(entity,id,b);access.audit("EDITAR",entity,id,"Registro actualizado");return safe(entity,db.get(entity,id));}
 @Transactional public void delete(String entity,long id){access.entity(entity,"write");serialize();var old=db.lock(entity,id);boolean draft=List.of("payrolls","fees","benefits","settlements").contains(entity)&&str(old,"status").equals("BORRADOR");require((!Boolean.TRUE.equals(cat.entity(entity).get("readonly"))||draft)&&!List.of("company","users","cash_accounts","periods","assets","purchases","orders").contains(entity),"No se elimina este registro; usa sus acciones o cambia su estado");if(entity.equals("budgets"))require(dec(old,"executed").signum()==0,"El presupuesto tiene ejecución");db.exec("DELETE FROM "+entity+" WHERE id=?",id);access.audit("ELIMINAR",entity,id,"Registro eliminado");}
 @Transactional public Object action(String entity,long id,String action,Map<String,Object>b){access.entity(entity,List.of("recipe","clean","bill","send","convert").contains(action)?"write":"approve");serialize();var row=db.lock(entity,id);if(!str(b,"file_id").isBlank()){var evidence=db.one("SELECT * FROM files WHERE id=?",str(b,"file_id"));access.module(str(evidence,"module"),"read");}String status=str(row,"status");Object result=map("ok",true);
 switch(entity+":"+action){
 case "purchases:send"->{require(status.equals("BORRADOR"),"La compra ya fue procesada");db.update(entity,id,map("status","ENVIADO"));}
 case "purchases:receive"->inventory.receive(id,b);
 case "purchases:cancel"->{require(List.of("BORRADOR","ENVIADO").contains(status),"No se anulan compras con recepciones");db.update(entity,id,map("status","ANULADO"));}
 case "payables:pay","receivables:pay"->ledger.pay(entity,id,b);
 case "payables:reschedule","receivables:reschedule"->{require(!List.of("PAGADA","ANULADA").contains(status),"La cuenta está cerrada");require(!str(b,"reason").isBlank(),"Indica el motivo");db.update(entity,id,map("due_date",LocalDate.parse(str(b,"due_date")),"notes",str(row,"notes")+" | Reprogramación: "+str(b,"reason")));}
 case "payables:credit","receivables:credit"->{var amount=money(dec(b,"amount"));positive(amount);require(!str(b,"reason").isBlank(),"Indica la referencia de la nota");require(!List.of("PAGADA","ANULADA").contains(status),"La cuenta está cerrada");require(str(row,"source").equals("MANUAL"),"Las notas a documentos integrados requieren su flujo tributario; esta acción admite cuentas manuales");var credit=dec(row,"credit").add(amount);require(credit.add(dec(row,"paid")).compareTo(dec(row,"total"))<=0,"La nota supera el saldo");db.update(entity,id,map("credit",credit,"status",credit.add(dec(row,"paid")).compareTo(dec(row,"total"))==0?"PAGADA":"PARCIAL"));ledger.simple(entity.equals("receivables")?"501":"421",entity.equals("receivables")?"121":"659",amount,"Nota interna "+str(b,"reason"),entity+":"+id);}
 case "leaves:approve","payrolls:approve","fees:approve","benefits:approve","settlements:approve"->hr.approve(entity,id);
 case "leaves:reject"->{require(status.equals("PENDIENTE"),"Solicitud procesada");db.update(entity,id,map("status","RECHAZADA"));}
 case "fees:cancel"->{require(status.equals("BORRADOR"),"El honorario ya fue enviado a Finanzas");require(!str(b,"reason").isBlank(),"Indica el motivo");db.update(entity,id,map("status","CANCELADO","notes",str(b,"reason")));}
 case "loans:settle"->hr.settle(id,id(b,"cash_account_id"));
 case "assets:depreciate"->{require(status.equals("ACTIVO"),"Activo dado de baja");YearMonth month=YearMonth.parse(str(b,"period"));require(!month.isAfter(YearMonth.from(today()))&&!month.isBefore(YearMonth.from(LocalDate.parse(str(row,"date")))),"Período de depreciación inválido");var base=dec(row,"amount").subtract(dec(row,"residual"));var amount=money(base.divide(dec(row,"useful_months"),2,RoundingMode.HALF_UP)).min(base.subtract(dec(row,"depreciated")));positive(amount);db.insert("depreciation_runs",map("asset_id",id,"period",month.toString(),"amount",amount));ledger.journal("Depreciación "+str(row,"name"),"DEPRECIACION:"+id+":"+month,month.atEndOfMonth(),List.of(ledger.entry("681",amount,BigDecimal.ZERO),ledger.entry("391",BigDecimal.ZERO,amount)));db.update(entity,id,map("depreciated",dec(row,"depreciated").add(amount)));}
 case "assets:retire"->{require(status.equals("ACTIVO"),"El activo ya está dado de baja");require(!str(b,"reason").isBlank(),"Indica el motivo");var amount=dec(row,"amount");var dep=dec(row,"depreciated");ledger.journal("Baja "+str(row,"name"),"BAJA:"+id,today(),List.of(ledger.entry("391",dep,BigDecimal.ZERO),ledger.entry("659",amount.subtract(dep),BigDecimal.ZERO),ledger.entry("331",BigDecimal.ZERO,amount)));db.update(entity,id,map("status","BAJA"));}
 case "dining_tables:clean"->{require(status.equals("LIMPIAR"),"La mesa no está pendiente de limpieza");db.update(entity,id,map("status","LIBRE"));}
 case "dishes:recipe"->{db.exec("DELETE FROM recipes WHERE dish_id=?",id);Set<Long> seen=new HashSet<>();for(var l:lines(b)){long product=id(l,"product_id");require(seen.add(product),"Ingrediente duplicado");positive(dec(l,"quantity"));db.insert("recipes",map("dish_id",id,"product_id",product,"quantity",dec(l,"quantity"),"process",str(l,"process")));}}
 case "orders:bill"->sales.bill(id,b);
 case "orders:checkout"->result=sales.checkout(id,b);
 case "orders:cancel"->sales.cancel(id,str(b,"reason"));
 case "quotes:accept","quotes:reject"->{require(status.equals("COTIZAR"),"La cotización ya fue atendida");db.update(entity,id,map("status",action.equals("accept")?"ACEPTADA":"RECHAZADA"));}
 case "quotes:convert"->result=map("order_id",sales.convert(id,b));
 case "quotes:deposit"->sales.deposit(id,b);
 case "quotes:cancel"->sales.cancelQuote(id,str(b,"reason"));
 case "invoices:void"->sales.voidInvoice(id,str(b,"reason"));
 case "cash_sessions:close"->{require(status.equals("ABIERTA"),"La caja está cerrada");require(b.containsKey("counted"),"Ingresa el efectivo contado");var counted=money(dec(b,"counted"));require(counted.signum()>=0,"Monto inválido");var expected=dec(db.lock("cash_accounts",id(row,"cash_account_id")),"balance");db.update(entity,id,map("status","CERRADA","expected",expected,"counted",counted,"difference",counted.subtract(expected),"closed_at",LocalDateTime.now().toString(),"closed_by",Security.user().id()));}
 case "journals:reverse"->{require(status.equals("REGISTRADO")&&str(row,"reference").startsWith("MANUAL"),"Solo se reversan asientos manuales desde aquí");ledger.journal("Reversa: "+str(row,"description"),"REVERSA:"+id,today(),db.rows("SELECT account_id,credit AS debit,debit AS credit FROM journal_lines WHERE journal_id=?",id));db.update(entity,id,map("status","REVERSADO"));}
 case "stock_rules:suggest"->{long supplier=id(row,"supplier_id");require(supplier>0,"Asigna un proveedor a esta alerta");var stock=db.sum("SELECT COALESCE(SUM(quantity),0) FROM stocks WHERE product_id=? AND warehouse_id=?",id(row,"product_id"),id(row,"warehouse_id"));var qty=dec(row,"maximum").subtract(stock);positive(qty);var p=db.get("products",id(row,"product_id"));var body=map("lines",List.of(map("product_id",p.get("id"),"quantity",qty,"unit_cost",p.get("average_cost"))));var clean=map("code","OC-"+UUID.randomUUID().toString().substring(0,8).toUpperCase(),"partner_id",supplier,"warehouse_id",row.get("warehouse_id"),"date",today(),"due_date",today().plusDays(7),"status","BORRADOR","total",0,"notes","Sugerida por reabastecimiento");result=map("purchase_id",inventory.purchase(body,clean));}
 default->throw new Problem(422,"Acción no disponible");}
 access.audit(action.toUpperCase(),entity,id,str(b,"reason"));return result;}
 @Transactional public Object stock(Map<String,Object>b){access.module("logistics","write");serialize();LocalDate date=LocalDate.parse(str(b,"date"));require(!date.isAfter(today())&&!date.isBefore(today().minusDays(4)),"La fecha solo puede ser hoy o hasta cuatro días anteriores");var amount=inventory.move(id(b,"product_id"),id(b,"warehouse_id"),str(b,"kind"),dec(b,"quantity"),dec(b,"unit_cost"),date,"MANUAL",str(b,"notes"));boolean incoming=List.of("INGRESO","AJUSTE_ENTRADA").contains(str(b,"kind"));if(amount.signum()>0)ledger.journal("Movimiento manual de inventario","MANUAL-STOCK",date,List.of(ledger.entry(incoming?"201":"659",amount,BigDecimal.ZERO),ledger.entry(incoming?"501":"201",BigDecimal.ZERO,amount)));access.audit("MOVIMIENTO","stock_moves",0,str(b,"notes"));return map("ok",true);}
 @Transactional public Object manualJournal(Map<String,Object>b){access.module("accounting","write");serialize();long id=ledger.journal(str(b,"description"),"MANUAL:"+str(b,"reference"),LocalDate.parse(str(b,"date")),lines(b));access.audit("ASIENTO","journals",id,str(b,"description"));return map("id",id);}
 @Transactional public Object transfer(Map<String,Object>b){access.module("accounting","approve");serialize();long from=id(b,"from_id"),to=id(b,"to_id");require(from!=to,"Las cuentas deben ser distintas");var amount=dec(b,"amount");positive(amount);ledger.cash(from,amount,"EGRESO","Transferencia a cuenta #"+to,"TRANSFERENCIA","");ledger.cash(to,amount,"INGRESO","Transferencia desde cuenta #"+from,"TRANSFERENCIA","");ledger.simple(ledger.cashCode(to),ledger.cashCode(from),amount,"Transferencia entre cuentas","TRANSFERENCIA");access.audit("TRANSFERENCIA","treasury",0,"Cuentas "+from+" → "+to);return map("ok",true);}
 @Transactional public Object lineAction(long id,String action,Map<String,Object>b){access.module("sales","read");String role=Security.user().role();if(!role.equals("ADMIN")){if(List.of("cook","ready","waste").contains(action))require(role.equals("COCINA"),"Acción reservada a cocina");else require(role.equals("SALON")||role.equals("CAJA"),"Acción reservada al salón");}serialize();sales.line(id,action,b);access.audit(action.toUpperCase(),"order_lines",id,str(b,"reason"));return map("ok",true);}
 @Transactional public Object addOrderLines(long id,Map<String,Object>b){access.module("sales","write");serialize();sales.addLines(id,lines(b));access.audit("AGREGAR_PLATOS","orders",id,"");return map("ok",true);}
}
